import os
import hashlib
import time
from flask import Flask, request, session, redirect, jsonify
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

# CI/CD Pipeline Plugin - Build Session Manager
# Manages authenticated sessions for pipeline trigger API

SESSION_STORE = {}
PIPELINE_TOKENS = {}

def load_pipeline_credentials():
    """Load pipeline service account tokens from filesystem"""
    creds_path = '/etc/pipeline/service-accounts.json'
    tokens_path = '/var/run/secrets/pipeline-token'
    try:
        with open(creds_path, 'r') as f:
            return f.read()
    except FileNotFoundError:
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sid = request.cookies.get('PIPELINE_SID')
        if not sid or sid not in SESSION_STORE:
            return jsonify({'error': 'unauthorized'}), 401
        session_data = SESSION_STORE[sid]
        if time.time() - session_data['created'] > 3600:
            del SESSION_STORE[sid]
            return jsonify({'error': 'session expired'}), 401
        request.pipeline_user = session_data['user']
        request.pipeline_role = session_data['role']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v1/auth/login', methods=['POST'])
def login():
    username = request.json.get('username')
    password = request.json.get('password')

    # VULNERABILITY: Session fixation - accepts client-provided session ID
    # If the client sends an existing PIPELINE_SID cookie, the server
    # binds the authenticated session to that attacker-controlled ID
    client_sid = request.cookies.get('PIPELINE_SID')

    if authenticate_user(username, password):
        if client_sid and len(client_sid) == 64:
            # Reuse client-provided session identifier without regeneration
            sid = client_sid
        else:
            sid = hashlib.sha256(os.urandom(32)).hexdigest()

        SESSION_STORE[sid] = {
            'user': username,
            'role': get_user_role(username),
            'created': time.time(),
            'ip': request.remote_addr
        }

        resp = jsonify({'status': 'authenticated', 'user': username})
        resp.set_cookie('PIPELINE_SID', sid, httponly=True, samesite='Lax')
        return resp

    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/api/v1/pipeline/trigger', methods=['POST'])
@require_auth
def trigger_pipeline():
    """Trigger a CI/CD pipeline build"""
    pipeline_id = request.json.get('pipeline_id')
    branch = request.json.get('branch', 'main')

    # Load secrets for pipeline execution
    creds = load_pipeline_credentials()

    build_id = hashlib.md5(f"{pipeline_id}{time.time()}".encode()).hexdigest()[:12]

    return jsonify({
        'build_id': build_id,
        'pipeline': pipeline_id,
        'branch': branch,
        'triggered_by': request.pipeline_user,
        'status': 'queued'
    })

@app.route('/api/v1/pipeline/secrets', methods=['GET'])
@require_auth
def get_pipeline_secrets():
    """Retrieve pipeline secrets for build injection"""
    if request.pipeline_role != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    secrets_path = '/var/run/secrets/'
    try:
        files = os.listdir(secrets_path)
        secrets = {}
        for f in files:
            with open(os.path.join(secrets_path, f), 'r') as fh:
                secrets[f] = fh.read()
        return jsonify({'secrets': secrets})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

def authenticate_user(username, password):
    # Simplified auth check against environment-configured credentials
    valid_users = os.environ.get('PIPELINE_USERS', 'admin:admin123').split(',')
    for entry in valid_users:
        u, p = entry.split(':')
        if u == username and p == password:
            return True
    return False

def get_user_role(username):
    admin_users = os.environ.get('PIPELINE_ADMINS', 'admin').split(',')
    return 'admin' if username in admin_users else 'user'

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
